Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_avaGraduaredPrice">_avaGraduaredPrice</param>
/// <returns>_avaGraduaredPrice</returns>
public boolean parmAVAGraduatedPrice(AVAGraduatedPrice     _avaGraduaredPrice = avaGraduatedPrice)
{
    avaGraduatedPrice   = _avaGraduaredPrice;
    return avaGraduatedPrice;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_qtyFrom">_qtyFrom</param>
/// <param name = "_qtyTo">_qtyTo</param>
/// <param name = "_priceDisctable">_priceDisctable</param>
/// <returns>boolean</returns>
protected boolean doesQuantityQualifyForFindingPriceAgreement(AmountQty _qtyFrom, AmountQuantityTo _qtyTo, PriceDiscTable _priceDisctable)
{
    boolean ret = next doesQuantityQualifyForFindingPriceAgreement(_qtyFrom,_qtyTo,_priceDisctable);
    if (priceDiscPriceAgreementSearchParameters.parmAVAGraduatedPrice() == NoYes::Yes && _priceDisctable.AVAGraduatedPrice == NoYes::Yes )
    {
        ret = true;
    }
    return ret;

}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_priceDiscTable">PriceDiscTable</param>
/// <returns>boolean</returns>
protected boolean checkAdditionalQualificationForFindingPriceAgreement(PriceDiscTable _priceDiscTable)
{
    boolean ret = next checkAdditionalQualificationForFindingPriceAgreement(_priceDiscTable);
    if (priceDiscPriceAgreementSearchParameters.parmAVAGraduatedPrice() == NoYes::Yes && _priceDiscTable.AVAGraduatedPrice == NoYes::Yes)
    {
        InventTable inventTable = InventTable::find(priceDiscPriceAgreementSearchParameters.parmItemId());
        if (inventTable.PrimaryVendorId != _priceDiscTable.AccountRelation)
        {
            ret = false;
        }
    }
    return ret;
}
